interface PricingStrategy { double price(double qty); }        // Strategy

final class WholesalePricing implements PricingStrategy {       // ConcreteStrategy
    private final double discount;
    WholesalePricing(double discount) { this.discount = discount; }
    public double price(double qty) { return qty * (1 - discount); }
}

final class Checkout {                                          // Context
    private PricingStrategy pricing;
    Checkout(PricingStrategy pricing) { this.pricing = pricing; }
    double total(double qty) { return pricing.price(qty); }
}
